export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceKeyboard: (callback: (payload: boolean) => void) => listen<boolean>("appearance.keyboard", callback),
	appearanceLines: (callback: (payload: Lines) => void) => listen<Lines>("appearance.lines", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearancePosture: (callback: (payload: Posture) => void) => listen<Posture>("appearance.posture", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	handwritingChanged: (callback: (payload: null) => void) => listen<null>("handwriting.changed", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
	languageChanged: (callback: (payload: null) => void) => listen<null>("language.changed", callback),
	powerBattery: (callback: (payload: boolean) => void) => listen<boolean>("power.battery", callback),
	recordingFailed: (callback: (payload: string) => void) => listen<string>("recording.failed", callback),
	recordingLevel: (callback: (payload: number) => void) => listen<number>("recording.level", callback),
	speechChanged: (callback: (payload: null) => void) => listen<null>("speech.changed", callback),
	windowPresent: (callback: (payload: null) => void) => listen<null>("window.present", callback),
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	library: string,
	launchPaths: string[],
} & Appearance;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	lines: Lines,
	posture: Posture,
	keyboard: boolean,
	locale: Locale,
};

export type Corners = "rounded" | "square";

export type Definition = {
	term: string,
	meaning: string,
	at: number,
};

export type Download = {
	received: number,
	total: number,
	problem: string | null,
};

export type Engine = "parakeet" | "whisper";

export type Entry = {
	folder: string,
	meta: Value,
};

export type HandwritingDownload = {
	received: number,
	total: number,
	problem: string | null,
};

export type HandwritingModel = {
	name: string,
	licence: string,
	credit: string,
	homepage: string,
	size: number,
	installed: boolean,
	download: HandwritingDownload | null,
};

export type Heading = {
	title: string,
	summary: string,
};

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type Kind = "pdf" | "image" | "importable";

export type LanguageDownload = {
	received: number,
	total: number,
	problem: string | null,
};

export type LanguageModel = {
	name: string,
	licence: string,
	credit: string,
	homepage: string,
	size: number,
	installed: boolean,
	download: LanguageDownload | null,
};

export type Library = {
	root: string,
	subjects: Subject[],
};

/**
 *  Something said in class, with when it was said in milliseconds from the
 *  start of the recording.
 */
export type Line = {
	at: number,
	text: string,
};

export type Lines = "none" | "lines" | "scanlines";

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Model = {
	id: string,
	engine: Engine,
	name: string,
	licence: string,
	credit: string,
	homepage: string,
	size: number,
	installed: boolean,
	usage: number,
	download: Download | null,
};

export type Motion = "full" | "reduced" | "off";

/**
 *  Notes of part of a class. Each item has when it was said, so it leads back
 *  to its moment in the recording.
 */
export type Notes = {
	points: Point[],
	definitions: Definition[],
	homework: Task[],
	questions: Question[],
};

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type Point = {
	text: string,
	at: number,
};

/**  Whether the computer is used as a laptop or folded into a tablet. */
export type Posture = "laptop" | "tablet";

export type PowerState = {
	battery: boolean,
	onBattery: boolean,
};

export type Question = {
	question: string,
	answer: string | null,
	at: number,
};

export type Read = { kind: "text"; text: string } | { kind: "notInstalled" } | { kind: "paused" } | { kind: "missing" };

export type RecordingState = {
	path: string,
	length: number,
	paused: boolean,
};

/**
 *  Something said in a recording, with when it starts and ends in milliseconds
 *  from the start of the recording, and the language it was said in.
 */
export type Said = {
	start: number,
	end: number,
	language: string,
	text: string,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Subject = {
	notebooks: Entry[],
} & Entry;

export type Task = {
	task: string,
	/**  When it's due, as the teacher said it, such as "next Tuesday". */
	due: string | null,
	at: number,
};

/**
 *  What a recording says from where it was asked for, up to `next`, where the
 *  next request goes on from.
 */
export type Transcribed = {
	said: Said[],
	next: number,
	/**  Whether the whole recording has been transcribed. */
	done: boolean,
};

export type Transcription = { kind: "done"; transcribed: Transcribed } | { kind: "notInstalled" } | { kind: "paused" } | { kind: "unsupported" } | { kind: "missing" };

export type Trashed = {
	id: string,
	from: string,
	trashedAt: number,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

export type Written<T> = { kind: "done"; written: T } | { kind: "notInstalled" } | { kind: "paused" } | { kind: "missing" };
